COMMENT ON COLUMN org_chain.updated_at IS 'Thời điểm cập nhật gần nhất của bản ghi';
COMMENT ON TABLE legal_entity IS 'Pháp nhân chịu trách nhiệm doanh thu, nhân sự, báo cáo tài chính và hóa đơn.';
COMMENT ON COLUMN legal_entity.legal_entity_id IS 'Khóa chính do Oracle cấp để định danh bản ghi. Pháp nhân chịu trách nhiệm doanh thu, nhân sự, báo cáo tài chính và hóa đơn';
