COMMENT ON COLUMN legal_entity.updated_at IS 'Thời điểm cập nhật gần nhất của bản ghi';
COMMENT ON TABLE legal_entity_profile IS 'Lịch sử tên, mã số thuế và địa chỉ pháp nhân theo thời gian hiệu lực.';
COMMENT ON COLUMN legal_entity_profile.entity_profile_id IS 'Khóa chính do Oracle cấp để định danh bản ghi. Lịch sử tên, mã số thuế và địa chỉ pháp nhân theo thời gian hiệu lực';
COMMENT ON COLUMN legal_entity_profile.legal_entity_id IS 'Mã tham chiếu tới Pháp nhân chịu trách nhiệm doanh thu, nhân sự, báo cáo tài chính và hóa đơn';
COMMENT ON COLUMN legal_entity_profile.version_no IS 'thứ tự phiên bản dùng trong Lịch sử tên, mã số thuế và địa chỉ pháp nhân theo thời gian hiệu lực.; tuân theo giới hạn nghiệp vụ';
