COMMENT ON COLUMN audit_event.object_id IS 'Đối tượng định danh của Nhật ký thao tác để kiểm soát, truy vết và đối chiếu nghiệp vụ';
COMMENT ON COLUMN audit_event.trace_id IS 'Mã truy vết định danh của Nhật ký thao tác để kiểm soát, truy vết và đối chiếu nghiệp vụ';
COMMENT ON COLUMN audit_event.before_data IS 'Dữ liệu trước thay đổi; chỉ lưu trường cần truy vết, loại bỏ bí mật không cần thiết';
COMMENT ON COLUMN audit_event.after_data IS 'Dữ liệu sau thay đổi; chỉ lưu trường cần truy vết, loại bỏ bí mật không cần thiết';
COMMENT ON COLUMN audit_event.source_ip IS 'Nguồn địa chỉ IP của Nhật ký thao tác để kiểm soát, truy vết và đối chiếu nghiệp vụ';
COMMENT ON COLUMN audit_event.occurred_at IS 'Thời điểm occurred được ghi nhận; có lưu múi giờ';
COMMENT ON TABLE integration_outbox IS 'Sự kiện chờ gửi dịch vụ ngoài, hỗ trợ thử lại và chống gửi trùng.';
COMMENT ON COLUMN integration_outbox.outbox_event_id IS 'Khóa chính do Oracle cấp để định danh bản ghi. Sự kiện chờ gửi dịch vụ ngoài, hỗ trợ thử lại và chống gửi trùng';
COMMENT ON COLUMN integration_outbox.aggregate_type IS 'Loại đối tượng tổng hợp của Sự kiện chờ gửi dịch vụ ngoài, hỗ trợ thử lại và chống gửi trùng';
COMMENT ON COLUMN integration_outbox.aggregate_id IS 'Đối tượng tổng hợp định danh của Sự kiện chờ gửi dịch vụ ngoài, hỗ trợ thử lại và chống gửi trùng';
COMMENT ON COLUMN integration_outbox.event_type IS 'Loại sự kiện của Sự kiện chờ gửi dịch vụ ngoài, hỗ trợ thử lại và chống gửi trùng';
COMMENT ON COLUMN integration_outbox.idempotency_key IS 'Khóa để consumer không thực hiện nghiệp vụ hai lần khi nhận lại sự kiện';
COMMENT ON COLUMN integration_outbox.payload IS 'Dữ liệu gửi/nhận hoặc dữ liệu đối chiếu; không lưu bí mật không cần thiết';
COMMENT ON COLUMN integration_outbox.event_status IS 'Trạng thái nghiệp vụ; các giá trị được ràng buộc: PENDING, PROCESSING, PROCESSED, RETRY, DEAD';
COMMENT ON COLUMN integration_outbox.attempt_count IS 'lần thử số lần dùng trong Sự kiện chờ gửi dịch vụ ngoài, hỗ trợ thử lại và chống gửi trùng.; tuân theo giới hạn nghiệp vụ';
COMMENT ON COLUMN integration_outbox.available_at IS 'Thời điểm sẵn sàng được ghi nhận; có lưu múi giờ';
COMMENT ON COLUMN integration_outbox.created_at IS 'Thời điểm tạo bản ghi; có lưu múi giờ để phục vụ đối soát';
COMMENT ON COLUMN integration_outbox.processed_at IS 'Thời điểm xử lý được ghi nhận; có lưu múi giờ';
COMMENT ON COLUMN integration_outbox.last_error IS 'Last error của Sự kiện chờ gửi dịch vụ ngoài, hỗ trợ thử lại và chống gửi trùng';
COMMENT ON TABLE app_setting IS 'Cấu hình nghiệp vụ có phạm vi và thời gian hiệu lực.';
COMMENT ON COLUMN app_setting.app_setting_id IS 'Khóa chính do Oracle cấp để định danh bản ghi. Cấu hình nghiệp vụ có phạm vi và thời gian hiệu lực';
COMMENT ON COLUMN app_setting.setting_key IS 'Khóa cấu hình của Cấu hình nghiệp vụ có phạm vi và thời gian hiệu lực';
COMMENT ON COLUMN app_setting.scope_type IS 'Loại phạm vi của Cấu hình nghiệp vụ có phạm vi và thời gian hiệu lực';
COMMENT ON COLUMN app_setting.scope_id IS 'Phạm vi định danh của Cấu hình nghiệp vụ có phạm vi và thời gian hiệu lực';
COMMENT ON COLUMN app_setting.value_type IS 'Loại giá trị của Cấu hình nghiệp vụ có phạm vi và thời gian hiệu lực';
COMMENT ON COLUMN app_setting.setting_value IS 'Giá trị cấu hình; diễn giải theo value_type và phạm vi hiệu lực';
COMMENT ON COLUMN app_setting.valid_from IS 'Thời điểm bắt đầu hiệu lực; dùng chọn quy tắc áp dụng tại thời điểm phát sinh nghiệp vụ';
COMMENT ON COLUMN app_setting.valid_to IS 'Thời điểm kết thúc hiệu lực; để trống nếu chưa xác định thời điểm kết thúc';
COMMENT ON COLUMN app_setting.description IS 'Mô tả của Cấu hình nghiệp vụ có phạm vi và thời gian hiệu lực';
COMMENT ON COLUMN app_setting.updated_by IS 'Mã tham chiếu tới Hồ sơ người dùng nghiệp vụ liên kết Keycloak; không lưu mật khẩu';
COMMENT ON COLUMN app_setting.updated_at IS 'Thời điểm cập nhật gần nhất của bản ghi';
COMMENT ON COLUMN sales_order_line.inventory_location_id IS 'Kho/quầy xuất sản phẩm F&B cho dòng đơn; không dùng cho dòng vé.';

